def describe(title,code):
    s=title.lower()
    for pattern,meaning in RULES:
        if re.search(pattern,s,re.IGNORECASE):
            return meaning
    return DOMAIN_CONTEXT.get(code,"Událost představuje významnou změnu business stavu nebo práv a povinností VZP.")
